"""Small manual Sonnet release critique. No raw pages, keys or model auto-adoption."""
import hashlib,json
from pathlib import Path
from bedrock_gateway import call_stream
R=Path(__file__).resolve().parents[1];P=R/'research/source-store/products-20261004';K=json.loads((R/'dist/data/business-backbone.json').read_text());D=json.loads((R/'dist/data/operations.json').read_text());report=json.loads((R/'data/product-discoverability-report.json').read_text())
public={'profiles':[{k:p[k] for k in ['id','title','definition','features','distinguish_from','source_ids','steps']} for p in K['product_profiles']],'source_types':[{k:s[k] for k in ['id','source_kind','scope','benchmark_admitted']} for s in K['product_sources']],'inventory_counts':{k:K['product_quality'][k] for k in ['inventory_count','inventory_mapped','inventory_gap','gap_step_count']},'unresolved_definitions':[{k:w[k] for k in ['id','title','actor_role','object_key','outcome_key','review_note']} for w in D['works'] if w['status']=='unresolved'],'query_report':{k:report[k] for k in ['query_count','checks','issues','semantic_mece_approved','full_screen_coverage_approved']}}
prompt='''WGSS independent product-quality critic. The user rejects reactive alias patching. Evaluate this proposed structural migration: official public source vocabulary discovery inventory with mandatory root mapped/gap disposition; product traits/lifecycle step results; request≠execution; hidden gaps visible; production search against independent queries+source terms; no global MECE certification. No provider UI benchmarks added. Existing lender/borrower role faults flagged unresolved rather than made-up fixes. JSON only {release_findings:[{severity,profile_ids:[],issue,required_fix}],accepted_limits:[],claims_to_forbid:[],next_definition_priorities:[]}. Check semantic misleading default mapping, regional aliases, broader-narrower product hierarchy, rate ratio responsibility, pending proof disguised as full coverage. Be critical but don't fabricate undefined result IDs or demand strict universal law from limited public productpages. Source types not prices/policies. Querypass!=semanticCE. You cannot approve global definitions. Short precise Korean; at most 12 findings. PUBLIC STRUCTURED INPUT:'''+json.dumps(public,ensure_ascii=False,separators=(',',':'))
sha=hashlib.sha256(prompt.encode()).hexdigest();out=P/('quality-final-'+sha[:12]+'.json')
if out.exists():print('cached final quality review');raise SystemExit(0)
(P/('quality-final-'+sha[:12]+'.prompt.txt')).write_text(prompt)
for attempt in range(1,4):
 try:
  raw=call_stream('claude-sonnet-5',prompt,max_tokens=8000);(P/f'quality-final-{sha[:12]}.raw-{attempt}.json').write_text(json.dumps(raw,ensure_ascii=False,indent=2));assert raw['finish_reason']=='stop','truncated';t=raw['response'];proposal=json.loads(t[t.find('{'):t.rfind('}')+1]);out.write_text(json.dumps({'model':raw['model'],'prompt_sha256':sha,'usage':raw['usage'],'proposal':proposal,'automatically_adopted':False},ensure_ascii=False,indent=2));print('final quality review completed',flush=True);break
 except Exception as e:print('final review attempt',attempt,type(e).__name__,flush=True)
else:raise RuntimeError('final quality review incomplete')
